var n={en:`A seller UI can invoke settlement directly, and buyers can publish reviews without a valid purchase. The order verification route vanished.`,ua:`Інтерфейс продавця викликає Settlement напряму, а покупці публікують відгуки без купівлі. Шлях перевірки через Orders зник.`};var r={en:[`Remove seller→settlement and buyer→reputation shortcuts.`,`Restore orders→settlement and review eligibility verification.`,`Explain payout ledger and duplicate webhook protection.`],ua:[`Прибери seller→settlement та buyer→reputation.`,`Віднови orders→settlement і перевірку права відгуку.`,`Поясни журнал виплат і захист від повторних вебхуків.`]};var o=[{en:`A seller cannot authorize their own payout from the browser.`,ua:`Продавець не може сам дозволити виплату з браузера.`},{en:`Settlement depends on validated order state.`,ua:`Розрахунок залежить від перевіреного стану замовлення.`}];var a={remove:[`orders->settlement`],add:[{from:`seller`,to:`settlement`,kind:`sync`,label:`Intentional defect / Навмисна помилка`},{from:`buyer`,to:`reputation`,kind:`sync`,label:`Intentional defect / Навмисна помилка`}]};var l={scenario:n,tasks:r,checks:o,mutations:a};export{o as checks,l as default,a as mutations,n as scenario,r as tasks};